\title{Not All Models Are Inflated: Profiling Contamination Dose-Response Across Model Families}

\author{Anonymous}

\begin{document}
\maketitle

\begin{abstract}
\input{abstract}
\end{abstract}

\input{introduction}
\input{related_work}
\input{method}
